import{_ as e,o as a,c as r,ag as d}from"./chunks/framework.Aev9KvMf.js";const f=JSON.parse('{"title":"体重管理指导原则（2024年版）","description":"国家卫健委《体重管理指导原则（2024年版）》要点整理：体重分类标准、管理评估与干预路径，出处可跳回原文对应页。","frontmatter":{"title":"体重管理指导原则（2024年版）","issuer":"国家卫生健康委办公厅","source_tier":"一级来源","version":"2024年版","published":"2024-12","source_url":"https://www.nhc.gov.cn/ylyjs/zcwj/202412/75cb79c171c94def9e768193e65484f7.shtml","status":"现行","tags":["体重管理","超重","肥胖","健康体重","行动清单"],"reviewed":false,"description":"国家卫健委《体重管理指导原则（2024年版）》要点整理：体重分类标准、管理评估与干预路径，出处可跳回原文对应页。"},"headers":[],"relativePath":"guides/weight-management-2024.md","filePath":"guides/weight-management-2024.md"}'),h={name:"guides/weight-management-2024.md"};function g(i,t,n,s,o,l){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="体重管理指导原则-2024年版" tabindex="-1">体重管理指导原则（2024年版） <a class="header-anchor" href="#体重管理指导原则-2024年版" aria-label="Permalink to &quot;体重管理指导原则（2024年版）&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本页由 AI 依据官方 PDF 原文整理，尚未逐条对照原文校验；校验通过前请以原文为准。</p></div><div class="danger custom-block"><p class="custom-block-title">使用须知</p><p>本页所有建议均<strong>整理自官方文件原文</strong>，每条&quot;出处&quot;均可点击直达原文对应页。本站不构成诊疗建议，与医生的治疗方案冲突时，<strong>以医嘱为准</strong>。</p></div><blockquote><p><strong>原文出处</strong>：国家卫生健康委办公厅印发，委托国家心血管病中心制定（<a href="https://www.nhc.gov.cn/ylyjs/zcwj/202412/75cb79c171c94def9e768193e65484f7.shtml" target="_blank" rel="noreferrer">通知页</a>）· 一级来源。下文&quot;出处&quot;链接指向本站镜像的<a href="https://yshuai.github.io/SageRelay/guides-pdf/weight-management-2024.pdf" target="_blank" rel="noreferrer">官方原文 PDF</a>（政府公文，属公共领域）。</p></blockquote><h2 id="这份文件适合谁" tabindex="-1">这份文件适合谁 <a class="header-anchor" href="#这份文件适合谁" aria-label="Permalink to &quot;这份文件适合谁&quot;">​</a></h2><p>开展体重管理工作的医疗卫生人员，以及想科学管理体重的一般人群（<a href="https://yshuai.github.io/SageRelay/guides-pdf/weight-management-2024.pdf#page=1" target="_blank" rel="noreferrer">原文·前言</a>）。</p><h2 id="速览卡-一屏看完" tabindex="-1">速览卡（一屏看完） <a class="header-anchor" href="#速览卡-一屏看完" aria-label="Permalink to &quot;速览卡（一屏看完）&quot;">​</a></h2><p>内容框架：<strong>体重的分类标准 → 体重管理相关评估 → 超重肥胖的干预和治疗 → 健康体重的管理与维持 → 特殊人群的体重管理 → 规范化体重管理流程</strong>。（<a href="https://yshuai.github.io/SageRelay/guides-pdf/weight-management-2024.pdf#page=2" target="_blank" rel="noreferrer">原文·目录</a>）</p><table tabindex="0"><thead><tr><th>关键标准</th><th>数值</th><th>出处</th></tr></thead><tbody><tr><td>健康体重</td><td>BMI <strong>18.5 ≤ BMI &lt; 24.0</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/weight-management-2024.pdf#page=2" target="_blank" rel="noreferrer">一</a></td></tr><tr><td>体重过低 / 超重 / 肥胖</td><td><strong>&lt;18.5 / 24.0≤BMI&lt;28.0 / ≥28.0</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/weight-management-2024.pdf#page=2" target="_blank" rel="noreferrer">一</a></td></tr><tr><td>减重目标</td><td>多数超重或轻度肥胖者：<strong>每周减 0.5～1kg</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/weight-management-2024.pdf#page=5" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>运动量</td><td>逐渐达到<strong>至少 250 分钟/周</strong>（或消耗 ≥2000kcal/周）中等至较大强度运动，分在每周 5～7 天</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/weight-management-2024.pdf#page=26" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>药物治疗指征</td><td>BMI≥28 且 3～6 个月生活方式干预减重不足 5%；或 BMI≥24 且合并高血压、高血糖等</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/weight-management-2024.pdf#page=9" target="_blank" rel="noreferrer">三</a></td></tr><tr><td>儿童活动</td><td>1～5 岁<strong>每日至少 180 分钟</strong>多样化身体活动；学龄儿童<strong>每日 ≥60 分钟</strong>中等以上强度</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/weight-management-2024.pdf#page=5" target="_blank" rel="noreferrer">三(一)</a></td></tr></tbody></table><h2 id="行动清单" tabindex="-1">行动清单 <a class="header-anchor" href="#行动清单" aria-label="Permalink to &quot;行动清单&quot;">​</a></h2><h3 id="🩺-了解管理路径" tabindex="-1">🩺 了解管理路径 <a class="header-anchor" href="#🩺-了解管理路径" aria-label="Permalink to &quot;🩺 了解管理路径&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环节</th><th>内容</th><th>出处</th></tr></thead><tbody><tr><td>分类</td><td>自己的 BMI 属于哪一类（见速览卡）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/weight-management-2024.pdf#page=2" target="_blank" rel="noreferrer">一</a></td></tr><tr><td>评估</td><td>病史、生活方式、体格/人体成分、医学检查、运动能力、特定人群评估</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/weight-management-2024.pdf#page=2" target="_blank" rel="noreferrer">二</a></td></tr><tr><td>干预</td><td>生活方式干预（膳食模式如 5+2 间歇性能量节食等）、药物治疗、手术治疗</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/weight-management-2024.pdf#page=4" target="_blank" rel="noreferrer">三</a>、<a href="https://yshuai.github.io/SageRelay/guides-pdf/weight-management-2024.pdf#page=5" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>维持</td><td>达标后仍需每周 200～300 分钟运动维持</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/weight-management-2024.pdf#page=26" target="_blank" rel="noreferrer">三(一)</a></td></tr></tbody></table><h3 id="🍚-吃-🏃-动" tabindex="-1">🍚 吃 / 🏃 动 <a class="header-anchor" href="#🍚-吃-🏃-动" aria-label="Permalink to &quot;🍚 吃 / 🏃 动&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>减重膳食在医生/营养师指导下选择，含间歇性能量节食等模式（连/非连续日每周禁食 2～3 天）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/weight-management-2024.pdf#page=6" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>运动循序渐进达到每周 250 分钟以上中等至较大强度</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/weight-management-2024.pdf#page=26" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>儿童青少年按年龄保证每日活动量（见速览卡）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/weight-management-2024.pdf#page=5" target="_blank" rel="noreferrer">三(一)</a></td></tr></tbody></table><h2 id="配套阅读" tabindex="-1">配套阅读 <a class="header-anchor" href="#配套阅读" aria-label="Permalink to &quot;配套阅读&quot;">​</a></h2><ul><li>饮食细节配合本站<a href="/SageRelay/guides/obesity-2024.html">《成人肥胖食养指南（2024年版）》</a>词条。</li></ul><h2 id="原文与溯源" tabindex="-1">原文与溯源 <a class="header-anchor" href="#原文与溯源" aria-label="Permalink to &quot;原文与溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>发布机构</td><td>国家卫生健康委办公厅</td></tr><tr><td>版本</td><td>2024 年版（现行）</td></tr><tr><td>发布时间</td><td>2024 年 12 月</td></tr><tr><td>原文直链</td><td><a href="https://www.nhc.gov.cn/ylyjs/zcwj/202412/75cb79c171c94def9e768193e65484f7.shtml" target="_blank" rel="noreferrer">卫健委通知页</a></td></tr></tbody></table>',18)])])}const u=e(h,[["render",g]]);export{f as __pageData,u as default};
